  global_feed_url: 'https://news.google.com/rss/search?q=(automotive%20OR%20car%20industry%20OR%20vehicle%20recall%20OR%20car%20service%20OR%20diagnostics)%20when%3A1d&hl=en-US&gl=US&ceid=US:en'
