  }
  if (hay.includes('gdansk') || hay.includes('gdańsk') || hay.includes('trojmiasto') || hay.includes('trójmiasto') || hay.includes('polska') || hay.includes('poland')) score += 4;
  if (hay.includes('dealer') || hay.includes('showroom')) score -= 4;
  const family = classifyFamily(item);
